function keyIndexConfig(file) {
    // Owner aliases do not change this home-relative physical setting.
    return file.root === 'home' && file.path === `${MODEL_PLUGIN}/key-index.json`;
}
function preferConfig(file, other) {
    return other === undefined || stamp(file) > stamp(other) || (stamp(file) === stamp(other) && hashJson(file.data) > hashJson(other.data)) ? file : other;
}
/** File timestamps select fields; refs and visible labels in the home index are additive. */
export function mergeConfigFiles(local = [], remote = []) {
    const merged = new Map();
    for (const file of [...remote, ...local]) {
        if (!declaration(file))
            throw new Error('插件配置路径或元数据无效');
        const other = merged.get(configKey(file));
        const preferred = preferConfig(file, other);
        const alternate = preferred === file ? other : file;
        merged.set(configKey(file), keyIndexConfig(preferred)
            ? { ...preferred, data: mergeKeyIndexData(preferred.data, alternate?.data) }
            : preferred);
    }
    const files = [...merged.values()].sort((a, b) => configKey(a).localeCompare(configKey(b)));
    validateConfigFiles(files);
    return files;
}

