function protectedIndexTarget(paths) {
    return paths.homeDir === undefined ? undefined : keyMutationTarget(join(paths.homeDir, `${MODEL_PLUGIN}/key-index.json`));
}
/** Hold the model queue before current reads, through backup and the final rename. */
export async function applyPluginConfigs(paths, read, part, before) {
    const files = part.configFiles ?? [];
    validateConfigFiles(files);
    const allowed = new Set(read.declarations.map(configKey));
    const authorized = [];
    for (const file of files) {
        if (!allowed.has(configKey(file)))
            continue; // preserved on wire, no local authorization to write it
        const root = rootOf(paths, file);
        if (root !== undefined)
            authorized.push({ file, target: join(root, file.path) });
    }
    const indexTarget = protectedIndexTarget(paths);
    const release = indexTarget !== undefined && authorized.some(({ target }) => keyMutationTarget(target) === indexTarget)
        ? await acquireKeyMutation(indexTarget) : undefined;
    try {
        const pending = [];
        const indexFiles = [];
        let indexCurrent;
        let indexRead = false;
        let indexPosition = 0;
        let bytes = 0;
        for (const { file, target } of authorized) {
            const isIndex = indexTarget !== undefined && keyMutationTarget(target) === indexTarget;
            const maxBytes = Math.min(CONFIG_MAX_FILE_BYTES, CONFIG_MAX_BYTES - bytes);
            let current;
            if (isIndex && indexRead) {
                current = indexCurrent;
                if ((current?.bytes.length ?? 0) > maxBytes)
                    throw new Error('插件配置不是普通文件或超过读取上限');
            }
            else {
                current = await readBounded(target, maxBytes);
                if (isIndex) {
                    indexCurrent = current;
                    indexRead = true;
                }
            }
            bytes += current?.bytes.length ?? 0;
            const data = current?.bytes.toString('base64');
            if (isIndex) {
                // A snapshot made before a queued model mutation is not a write plan.
                if (current?.signature !== read.versions[configKey(file)])
                    throw new Error('插件配置在同步期间已变化，请重试');
                mergeKeyIndexData(file.data); // validate every authorized alias, even a losing one
                if (indexFiles.length === 0)
                    indexPosition = pending.length;
                indexFiles.push(file);
                continue;
            }
            const portable = data === undefined ? undefined : portableData(file, data, paths);
            const desired = localData(file, data, paths);
            if (portable === file.data)
                continue;
            if (current?.signature !== read.versions[configKey(file)])
                throw new Error('插件配置在同步期间已变化，请重试');
            // Even explicit restore/import/undo must not roll the UI document backwards.
            if (data !== undefined && file.path === `${MODEL_PLUGIN}/ui-order.json` && stamp({ ...file, data }) > stamp(file))
                continue;
            pending.push({ file, target, signature: current?.signature, data: desired });
        }
        if (indexFiles.length > 0) {
            // Multiple authorized names for one physical index make one commit, not self-conflicting writes.
            const ranked = indexFiles.slice().sort((left, right) => {
                const time = stamp(right) - stamp(left);
                if (time !== 0)
                    return time;
                const a = hashJson(left.data), b = hashJson(right.data);
                return a === b ? 0 : a > b ? -1 : 1;
            });
            const preferred = ranked[0];
            let desired = preferred.data;
            for (const file of ranked.slice(1))
                desired = mergeKeyIndexData(desired, file.data);
            const data = indexCurrent?.bytes.toString('base64');
            desired = mergeKeyIndexData(desired, data);
            if (desired !== data)
                pending.splice(indexPosition, 0, { file: preferred, target: indexTarget, signature: indexCurrent?.signature, data: desired });
        }
        if (pending.length === 0)
            return false;
        await before(); // failure must abort, never overwrite without a backup
        for (const { file, target, signature, data } of pending) {
            await safePath(dirname(target), true);
            if ((await readBounded(target))?.signature !== signature)
                throw new Error('备份期间插件配置已变化，请重试');
            const temporary = join(dirname(target), `.webdav-config-${randomUUID()}.tmp`);
            const handle = await open(temporary, constants.O_WRONLY | constants.O_CREAT | constants.O_EXCL | (constants.O_NOFOLLOW ?? 0), 0o600);
            try {
                await handle.writeFile(Buffer.from(data, 'base64'));
                await handle.utimes(new Date(), new Date(file.modifiedAt));
                await handle.sync();
            }
            finally {
                await handle.close();
            }
            try {
                await safePath(dirname(target));
                if ((await readBounded(target))?.signature !== signature)
                    throw new Error('写入前插件配置已变化，请重试');
                await rename(temporary, target);
            }
            finally {
                await unlink(temporary).catch(() => undefined);
            }
        }
        return true;
    }
    finally {
        release?.();
    }
}
